import 'package:flutter/material.dart';import 'api.dart';import 'catalog.dart';
class CartItem{final Product product;final String size,color;int quantity;CartItem(this.product,this.size,this.color,{this.quantity=1});double get total=>product.price*quantity;}
class CartStore extends ChangeNotifier{CartStore._();static final instance=CartStore._();final List<CartItem> items=[];void add(Product p,String s,String c){final i=items.indexWhere((x)=>x.product.id==p.id&&x.size==s&&x.color==c);if(i>=0)items[i].quantity++;else items.add(CartItem(p,s,c));notifyListeners();}void change(CartItem x,int d){x.quantity+=d;if(x.quantity<=0)items.remove(x);notifyListeners();}double get subtotal=>items.fold(0,(s,x)=>s+x.total);void clear(){items.clear();notifyListeners();}}
class CartPage extends StatelessWidget{const CartPage({super.key});@override Widget build(BuildContext context)=>SafeArea(child:AnimatedBuilder(animation:CartStore.instance,builder:(context,_){final c=CartStore.instance;if(c.items.isEmpty)return const Center(child:Text('Корзина пуста',style:TextStyle(fontSize:24,fontWeight:FontWeight.bold)));return Column(children:[const Padding(padding:EdgeInsets.all(16),child:Align(alignment:Alignment.centerLeft,child:Text('Корзина',style:TextStyle(fontSize:28,fontWeight:FontWeight.bold)))),Expanded(child:ListView.builder(itemCount:c.items.length,itemBuilder:(context,i){final x=c.items[i];return ListTile(title:Text(x.product.name),subtitle:Text('${x.size} • ${x.color} • ${x.product.price.toStringAsFixed(0)} с.'),trailing:Row(mainAxisSize:MainAxisSize.min,children:[IconButton(onPressed:()=>c.change(x,-1),icon:const Icon(Icons.remove)),Text('${x.quantity}'),IconButton(onPressed:()=>c.change(x,1),icon:const Icon(Icons.add))]));})),Padding(padding:const EdgeInsets.all(16),child:SizedBox(width:double.infinity,child:FilledButton(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const CheckoutPage())),child:Text('Оформить • ${c.subtotal.toStringAsFixed(0)} сомони'))))]);}));}
class CheckoutPage extends StatefulWidget{const CheckoutPage({super.key});@override State<CheckoutPage> createState()=>_CheckoutPageState();}class _CheckoutPageState extends State<CheckoutPage>{String delivery='Courier';double deliveryFee=0;bool loading=true;final name=TextEditingController(),phone=TextEditingController(),address=TextEditingController(),comment=TextEditingController();@override void initState(){super.initState();ApiClient.instance.orderOptions().then((x){if(mounted)setState((){deliveryFee=(x['deliveryFee']as num? ??0).toDouble();loading=false;});}).catchError((_){if(mounted)setState(()=>loading=false);});}@override void dispose(){name.dispose();phone.dispose();address.dispose();comment.dispose();super.dispose();}void next(){if(name.text.trim().isEmpty||phone.text.trim().isEmpty||(delivery=='Courier'&&address.text.trim().isEmpty)){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Заполните данные получателя и адрес доставки')));return;}Navigator.push(context,MaterialPageRoute(builder:(_)=>PaymentPage(delivery:delivery,recipientName:name.text.trim(),recipientPhone:phone.text.trim(),deliveryAddress:delivery=='Courier'?address.text.trim():'',deliveryComment:comment.text.trim(),deliveryFee:delivery=='Courier'?deliveryFee:0)));}@override Widget build(BuildContext context){final fee=delivery=='Courier'?deliveryFee:0;final total=CartStore.instance.subtotal+fee;return Scaffold(appBar:AppBar(title:const Text('Оформление заказа')),body:ListView(padding:const EdgeInsets.all(18),children:[RadioListTile(value:'Courier',groupValue:delivery,onChanged:(v)=>setState(()=>delivery=v!),title:const Text('Доставка курьером')),RadioListTile(value:'Pickup',groupValue:delivery,onChanged:(v)=>setState(()=>delivery=v!),title:const Text('Самовывоз')),const SizedBox(height:10),TextField(controller:name,decoration:const InputDecoration(labelText:'Имя получателя',border:OutlineInputBorder())),const SizedBox(height:12),TextField(controller:phone,keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'Телефон получателя',border:OutlineInputBorder())),if(delivery=='Courier')...[const SizedBox(height:12),TextField(controller:address,decoration:const InputDecoration(labelText:'Адрес доставки',hintText:'Город, улица, дом, квартира',border:OutlineInputBorder()))],const SizedBox(height:12),TextField(controller:comment,maxLines:3,decoration:const InputDecoration(labelText:'Комментарий к заказу',hintText:'Подъезд, этаж, ориентир или пожелания',border:OutlineInputBorder())),const SizedBox(height:20),ListTile(contentPadding:EdgeInsets.zero,title:const Text('Товары'),trailing:Text('${CartStore.instance.subtotal.toStringAsFixed(0)} с.')),ListTile(contentPadding:EdgeInsets.zero,title:Text(delivery=='Courier'?'Доставка':'Самовывоз'),trailing:Text(loading?'…':'${fee.toStringAsFixed(0)} с.')),const Divider(),ListTile(contentPadding:EdgeInsets.zero,title:const Text('Итого',style:TextStyle(fontWeight:FontWeight.bold)),trailing:Text('${total.toStringAsFixed(0)} с.',style:const TextStyle(fontWeight:FontWeight.bold))),FilledButton(onPressed:loading?null:next,child:const Text('Продолжить к оплате'))]));}}
class PaymentPage extends StatefulWidget{final String delivery,recipientName,recipientPhone,deliveryAddress,deliveryComment;final double deliveryFee;const PaymentPage({super.key,required this.delivery,required this.recipientName,required this.recipientPhone,required this.deliveryAddress,required this.deliveryComment,required this.deliveryFee});@override State<PaymentPage> createState()=>_PaymentPageState();}class _PaymentPageState extends State<PaymentPage>{String method='DADO Wallet';bool busy=false;Future<void> submit()async{setState(()=>busy=true);try{final c=CartStore.instance;final result=await ApiClient.instance.createOrder({'deliveryMethod':widget.delivery,'paymentMethod':method,'recipientName':widget.recipientName,'recipientPhone':widget.recipientPhone,'deliveryAddress':widget.deliveryAddress,'deliveryComment':widget.deliveryComment,'items':c.items.map((x)=>{'productId':x.product.id,'variant':'${x.size}/${x.color}','quantity':x.quantity}).toList()});c.clear();if(mounted)Navigator.pushAndRemoveUntil(context,MaterialPageRoute(builder:(_)=>OrderSuccessPage(number:result['number']?.toString()??'',total:(result['total']as num? ??0).toDouble(),delivery:result['deliveryMethod']?.toString()??widget.delivery)),(r)=>r.isFirst);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext context){final total=CartStore.instance.subtotal+widget.deliveryFee;return Scaffold(appBar:AppBar(title:const Text('Оплата')),body:ListView(padding:const EdgeInsets.all(18),children:[for(final m in ['DADO Wallet','Банковская карта','QR-оплата','Наличными'])RadioListTile(value:m,groupValue:method,onChanged:(v)=>setState(()=>method=v!),title:Text(m)),const SizedBox(height:10),Text('К оплате: ${total.toStringAsFixed(0)} сомони',style:const TextStyle(fontSize:20,fontWeight:FontWeight.bold)),const SizedBox(height:16),FilledButton(onPressed:busy?null:submit,child:Padding(padding:const EdgeInsets.all(14),child:busy?const CircularProgressIndicator():const Text('Создать заказ'))),const SizedBox(height:10),const Text('Итоговая сумма и доступный остаток повторно проверяются сервером.',style:TextStyle(fontSize:12,color:Colors.black54))]));}}
class OrderSuccessPage extends StatelessWidget{final String number,delivery;final double total;const OrderSuccessPage({super.key,required this.number,required this.total,required this.delivery});@override Widget build(BuildContext context)=>Scaffold(body:Center(child:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.check_circle,size:90,color:Colors.green),const Text('Заказ создан',style:TextStyle(fontSize:28,fontWeight:FontWeight.bold)),Text(number),const SizedBox(height:8),Text(delivery=='Pickup'?'Самовывоз':'Доставка курьером'),Text('${total.toStringAsFixed(0)} сомони',style:const TextStyle(fontSize:20,fontWeight:FontWeight.bold)),const SizedBox(height:8),const Text('Товар зарезервирован до оплаты.')]))));}
